import type { Localized } from "@/lib/i18n";

/**
 * Everything a city page shows and a city card does not: the history, the list
 * of structures, the "did you know" line and the extra gallery photos.
 *
 * It lives apart from `sites.ts` for one reason — `sites.ts` is imported by
 * every route, so anything inside it is downloaded to render the home page,
 * the map or a list of cards. This is the half only `/kent/$slug` and the
 * quiz need, and keeping it in its own module keeps it out of everyone else's
 * bundle.
 */
export type SiteDetail = {
  history: Localized;
  structures: Localized[];
  funFact: Localized;
};

const d = (
  hisTr: string,
  hisEn: string,
  structTr: string[],
  structEn: string[],
  factTr: string,
  factEn: string,
): SiteDetail => ({
  history: { tr: hisTr, en: hisEn },
  structures: structTr.map((tr, i) => ({ tr, en: structEn[i] ?? tr })),
  funFact: { tr: factTr, en: factEn },
});

